#!/usr/bin/env python3
"""Seeded dungeon generator.

Generates a 48x32 dungeon with 8-12 non-overlapping rectangular rooms
connected by L-shaped corridors. Everything that is not a room or a
corridor is wall.
"""

import argparse
import random

WIDTH = 48
HEIGHT = 32
MIN_ROOMS = 8
MAX_ROOMS = 12
BORDER = 1            # rooms must stay at least this far from the map edge
MAX_PLACE_ATTEMPTS = 500

WALL = "#"
FLOOR = "."


class Room:
    __slots__ = ("x", "y", "w", "h")

    def __init__(self, x: int, y: int, w: int, h: int) -> None:
        self.x, self.y, self.w, self.h = x, y, w, h

    @property
    def cx(self) -> int:
        return self.x + self.w // 2

    @property
    def cy(self) -> int:
        return self.y + self.h // 2

    def overlaps(self, other: "Room", pad: int = 0) -> bool:
        """True if the rooms overlap (optionally with a padding gap)."""
        return not (
            self.x + self.w + pad <= other.x
            or other.x + other.w + pad <= self.x
            or self.y + self.h + pad <= other.y
            or other.y + other.h + pad <= self.y
        )

    def tiles(self):
        for yy in range(self.y, self.y + self.h):
            for xx in range(self.x, self.x + self.w):
                yield xx, yy


def generate(seed: int) -> list[list[str]]:
    """Return the dungeon as a grid of single-character strings."""
    rng = random.Random(seed)
    grid = [[WALL] * WIDTH for _ in range(HEIGHT)]

    # --- Place 8-12 non-overlapping rooms -------------------------------
    target = rng.randint(MIN_ROOMS, MAX_ROOMS)
    rooms: list[Room] = []
    attempts = 0
    while len(rooms) < target:
        attempts += 1
        if attempts > MAX_PLACE_ATTEMPTS:
            raise RuntimeError("could not place all rooms")
        w = rng.randint(4, 9)
        h = rng.randint(3, 6)
        x = rng.randint(BORDER, WIDTH - BORDER - w)
        y = rng.randint(BORDER, HEIGHT - BORDER - h)
        candidate = Room(x, y, w, h)
        if all(not candidate.overlaps(r, pad=1) for r in rooms):
            rooms.append(candidate)
            for tx, ty in candidate.tiles():
                grid[ty][tx] = FLOOR

    # --- Connect consecutive room centers with L-shaped corridors -------
    for a, b in zip(rooms, rooms[1:]):
        if rng.random() < 0.5:
            _carve_h(grid, a.cx, b.cx, a.cy)
            _carve_v(grid, a.cy, b.cy, b.cx)
        else:
            _carve_v(grid, a.cy, b.cy, a.cx)
            _carve_h(grid, a.cx, b.cx, b.cy)

    return grid


def _carve_h(grid: list[list[str]], x1: int, x2: int, y: int) -> None:
    for x in range(min(x1, x2), max(x1, x2) + 1):
        grid[y][x] = FLOOR


def _carve_v(grid: list[list[str]], y1: int, y2: int, x: int) -> None:
    for y in range(min(y1, y2), max(y1, y2) + 1):
        grid[y][x] = FLOOR


def render(grid: list[list[str]]) -> str:
    return "\n".join("".join(row) for row in grid)


def main() -> None:
    parser = argparse.ArgumentParser(description="Seeded dungeon generator")
    parser.add_argument("--seed", type=int, default=0, help="random seed")
    args = parser.parse_args()
    print(render(generate(args.seed)))


if __name__ == "__main__":
    main()

