import hashlib

import pytest

from dungeon import (
    BORDER,
    FLOOR,
    HEIGHT,
    MAX_ROOMS,
    MIN_ROOMS,
    WIDTH,
    Room,
    generate,
)

SEEDS = range(1, 31)


def find_rooms(grid):
    """Recover room rectangles by scanning for solid rectangular floor blocks."""
    rooms = []
    seen = set()
    h, w = len(grid), len(grid[0])
    for y in range(h):
        for x in range(w):
            if grid[y][x] == FLOOR and (x, y) not in seen:
                # expand right then down to get the maximal rectangle of floors
                x2 = x
                while x2 + 1 < w and grid[y][x2 + 1] == FLOOR:
                    x2 += 1
                y2 = y
                while y2 + 1 < h and all(
                    grid[y2 + 1][xx] == FLOOR for xx in range(x, x2 + 1)
                ):
                    y2 += 1
                # only count it as a room if it's big enough to be one
                if (x2 - x + 1) >= 4 and (y2 - y + 1) >= 3:
                    rooms.append(Room(x, y, x2 - x + 1, y2 - y + 1))
                for yy in range(y, y2 + 1):
                    for xx in range(x, x2 + 1):
                        seen.add((xx, yy))
    return rooms


def flood_fill_size(grid):
    h, w = len(grid), len(grid[0])
    start = next(
        (x, y) for y in range(h) for x in range(w) if grid[y][x] == FLOOR
    )
    seen = {start}
    stack = [start]
    while stack:
        x, y = stack.pop()
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if (
                0 <= nx < w
                and 0 <= ny < h
                and grid[ny][nx] == FLOOR
                and (nx, ny) not in seen
            ):
                seen.add((nx, ny))
                stack.append((nx, ny))
    return seen


@pytest.fixture(scope="module")
def dungeons():
    return {seed: generate(seed) for seed in SEEDS}


def test_dimensions(dungeons):
    for grid in dungeons.values():
        assert len(grid) == HEIGHT
        assert all(len(row) == WIDTH for row in grid)


def test_room_count_within_bounds(dungeons):
    for grid in dungeons.values():
        assert MIN_ROOMS <= len(find_rooms(grid)) <= MAX_ROOMS


def test_rooms_do_not_overlap_and_avoid_border(dungeons):
    for grid in dungeons.values():
        rooms = find_rooms(grid)
        for r in rooms:
            assert r.x >= BORDER
            assert r.y >= BORDER
            assert r.x + r.w <= WIDTH - BORDER
            assert r.y + r.h <= HEIGHT - BORDER
        for i, a in enumerate(rooms):
            for b in rooms[i + 1:]:
                assert not a.overlaps(b)


def test_single_connected_component(dungeons):
    total_floor = sum(
        row.count(FLOOR) for grid in dungeons.values() for row in grid
    )
    assert total_floor > 0
    for grid in dungeons.values():
        assert len(flood_fill_size(grid)) == sum(row.count(FLOOR) for row in grid)


def test_deterministic_same_seed():
    for seed in SEEDS:
        h1 = hashlib.sha256("\n".join("".join(r) for r in generate(seed)).encode()).hexdigest()
        h2 = hashlib.sha256("\n".join("".join(r) for r in generate(seed)).encode()).hexdigest()
        assert h1 == h2


def test_different_seeds_yield_distinct_maps(dungeons):
    hashes = {
        hashlib.sha256("\n".join("".join(r) for r in grid).encode()).hexdigest()
        for grid in dungeons.values()
    }
    assert len(hashes) >= 25

