import hashlib

import pytest

from dungeon import (
    BORDER,
    FLOOR,
    HEIGHT,
    MAX_ROOMS,
    MIN_ROOMS,
    WIDTH,
    generate,
    generate_with_rooms,
)

SEEDS = range(1, 31)


def to_text(grid):
    return "\n".join("".join(row) for row in grid)


def flood_fill_size(grid):
    h, w = len(grid), len(grid[0])
    start = next(
        (x, y) for y in range(h) for x in range(w) if grid[y][x] == FLOOR
    )
    seen = {start}
    stack = [start]
    while stack:
        x, y = stack.pop()
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if (
                0 <= nx < w
                and 0 <= ny < h
                and grid[ny][nx] == FLOOR
                and (nx, ny) not in seen
            ):
                seen.add((nx, ny))
                stack.append((nx, ny))
    return seen


@pytest.fixture(scope="module")
def dungeons():
    return {seed: generate_with_rooms(seed) for seed in SEEDS}


def test_dimensions(dungeons):
    for grid, _ in dungeons.values():
        assert len(grid) == HEIGHT
        assert all(len(row) == WIDTH for row in grid)


def test_room_count_within_bounds(dungeons):
    for _, rooms in dungeons.values():
        assert MIN_ROOMS <= len(rooms) <= MAX_ROOMS


def test_rooms_do_not_overlap_and_avoid_border(dungeons):
    for _, rooms in dungeons.values():
        for r in rooms:
            assert r.x >= BORDER
            assert r.y >= BORDER
            assert r.x + r.w <= WIDTH - BORDER
            assert r.y + r.h <= HEIGHT - BORDER
        for i, a in enumerate(rooms):
            for b in rooms[i + 1:]:
                assert not a.overlaps(b)


def test_rooms_are_carved_as_floor(dungeons):
    for grid, rooms in dungeons.values():
        for r in rooms:
            for x in range(r.x, r.x + r.w):
                for y in range(r.y, r.y + r.h):
                    assert grid[y][x] == FLOOR


def test_single_connected_component(dungeons):
    for grid, _ in dungeons.values():
        floor_count = sum(row.count(FLOOR) for row in grid)
        assert floor_count > 0
        assert len(flood_fill_size(grid)) == floor_count


def test_deterministic_same_seed():
    for seed in SEEDS:
        h1 = hashlib.sha256(to_text(generate(seed)).encode()).hexdigest()
        h2 = hashlib.sha256(to_text(generate(seed)).encode()).hexdigest()
        assert h1 == h2


def test_different_seeds_yield_distinct_maps(dungeons):
    hashes = {
        hashlib.sha256(to_text(grid).encode()).hexdigest()
        for grid, _ in dungeons.values()
    }
    assert len(hashes) >= 25

